INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(38304, 'ruRU', 'Вал''шара', 'Поговорите с Малфурионом Штормгневом в Лор''латиле, в Вал''шаре.', '[PH] Пройдите через портал в Даларане и встретьтесь с Малфурионом Штормгневом в Вал''шаре.'),
(38305, 'ruRU', 'Кенарий, Хранитель рощи', 'Поговорите с Малфурионом Штормгневом в Лорлатиле, в Вал''шаре.', 'Приветствую тебя, герой.$b$bПриветствую в Вал''шаре. Целую эпоху я не ступал в эти драгоценные леса. Слишком долго...$b$bНаше дело здесь просто. Мы должны призвать моего наставника, Кенария, и узнать, где он хранит Слёзы Элуны. С ними ты будешь на шаг ближе к запечатыванию Гробницы Саргераса и пресечению замыслов Легиона.$b$bПеред тобой множество опасных заданий. Считай этот визит коротким отдыхом.$b$bИдём, это не займёт много времени.'),
(38552, 'ruRU', 'Гробница лорда Хал''шары', 'Разграбьте гробницу.', 'Гробница, я нашёл её.'),
(38607, 'ruRU', 'Врата Валхаллы', 'Поговорите с Ведиром.', 'Вырваться из хватки Хелии — не самый малый подвиг. Возможно, ты всё же окажешься достойным воином.\n\nСковальд вошёл в Валхаллу; у тебя остаётся всё меньше времени. Легион осквернил разум людей Сковальда. Отряд недостойных врайкулов пытается войти в портал к Валхалле.\n\nВеликаны, охраняющие врата, ведут бой, который им не выиграть. Натиску Легиона не видно конца.\n\nПоговори с драконом Ведиром внутри врат, у портала. Он поможет тебе в следующем задании.'),
(38648, 'ruRU', 'Приказы Вороньей Скалы', 'Вернитесь к командиру Джероду Песнь Теней в Брейденсбрук.', 'Письмо написано ночными чернилами:$B$B"Вторжение демонов неминуемо, но пока горят огни Вороньей Скалы, мы будем защищать земли калдораев. Убивайте любых чужаков, что встанут на нашем пути."$B$B- К.В.$B$BВозможно, Джерод Песнь Теней захочет это увидеть.'),
(38697, 'ruRU', 'Меч истины', 'Установите Фал''шатил на землю, затем победите ночных эльфов Вороньей Скалы в его святом свете.', 'Армия лорда Вороньей Скалы восстаёт из мёртвых, но я полагаю, что ею управляет воля Гул''дана.$B$BВозьми это — клинок лорда Вороньей Скалы, Фал''шатил. Он был известен своим уникальным магическим свойством. Те, кто смотрел в его зеркальное лезвие, не могли отрицать правду.$B$BВозьми клинок и вонзи его в землю. Атакуй призраков ночных эльфов рядом с его светом. Когда они ослабнут в его присутствии, возможно, к ним вернётся рассудок.'),
(38839, 'ruRU', 'Хватит ждать', 'Отправьтесь к южным скалам Вал''шары и поговорите с Макрой Шёпот Клинка.', 'Мама получила весть и сказала, что кровь требует крови. Она велела мне ждать здесь, пока она уйдёт, но прошло уже две недели. Я устал ждать.$B$BЯ останусь дома, если ты пойдёшь искать её. Она сказала, что отправляется к скалам далеко на юге.'),
(39011, 'ruRU', 'Вторжение Вороньей Скалы', 'Убейте 7 убийц Вороньей Скалы в Брейденсбруке.', 'Когда-то эти земли были мирными и процветающими. Затем мы увидели первые дурные знамения: странные недуги, испорченные посевы и тому подобное. Теперь призраки нападают на нас из того замка за рекой, а нежить-убийцы убивают наших рыбаков, чтобы отрезать деревню от пропитания.$B$BМы последняя семья, живущая так близко к замку, но мы не смеем отступить: эта река — лучший путь для рыбаков, чтобы доставлять улов в город. Прошу, не сразишься ли ты с этой нежитью?'),
(39032, 'ruRU', 'Призыв от Сайланны', 'Найдите Сайланну Дыхание Реки на Мелководье Лунного Крыла.', 'Духи природы всегда были озорными существами, но последнее время их озорство переросло в насилие.$B$BОдна из друидов, которую я зову подругой, Сайланна Дыхание Реки, сообщает, что они напали на гнездовья фей-драконов.$B$BМелководье Лунного Крыла лежит на юге. Там ты найдёшь Сайланну.'),
(39125, 'ruRU', 'Истребитель демонов', 'Убейте Призывателя гибели, Оскальную Пасть и Скрежетницепь', 'С демонами, распространяющими эту порчу, нужно разобраться. Убейте их генералов, и их планы рассыплются.\n\nУ меня для тебя подарок. Этот рог дал мне сам Один — используй его, чтобы сокрушить всех, кто встанет на твоём пути.\n\nБоги непременно будут благосклонны к тебе, если ты помешаешь продвижению Легиона.');
